        ?maxGeom a sf:Point ;
                 wgs84_pos:lat ?maxLat ;
                 wgs84_pos:long ?maxLon .
      }
      ORDER BY DESC(?maxElev)
      LIMIT 1
    }
    {
      SELECT ?minSensor ?minLat ?minLon
