        ?minObs a sosa:Observation ;
                hyobs:meanElevation ?minElev ;
                sosa:madeBySensor ?minSensor .
        ?minSensor geo:hasGeometry ?minGeom .
        ?minGeom a sf:Point ;
                 wgs84_pos:lat ?minLat ;
                 wgs84_pos:long ?minLon .
      }
      ORDER BY ASC(?minElev)
      LIMIT 1
    }
    BIND(
      sqrt(
        (
          (?maxLat - ?minLat) * 111320
        ) * (
          (?maxLat - ?minLat) * 111320
        ) +
        (
          (?maxLon - ?minLon) * 111320 * cos((?maxLat + ?minLat)/2 * 3.141592653589793/180)
        ) * (
          (?maxLon - ?minLon) * 111320 * cos((?maxLat + ?minLat)/2 * 3.141592653589793/180)
        )
      ) AS ?distanceMeters
    )
  }
}

